package pl.glyphtoy.aiready;

final class ClaudeFrames {
    static final int[] DELAYS = {130, 140, 130, 70, 60, 70, 70, 60, 70, 70, 60, 70};
    private static final String[] DATA = {
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
    };
    private static final int[][] FRAMES = decode();
    static int[] at(long time) {
        int elapsed = (int) (time % 1000);
        for (int i = 0; i < DELAYS.length; i++) {
            if (elapsed < DELAYS[i]) return FRAMES[i];
            elapsed -= DELAYS[i];
        }
        return FRAMES[0];
    }
    private static int[][] decode() {
        int[][] frames = new int[DATA.length][625];
        for (int i = 0; i < DATA.length; i++) for (int p = 0; p < 625; p++)
            frames[i][p] = Character.digit(DATA[i].charAt(p), 16) * 15;
        return frames;
    }
}
